def merge_intervals(intervals):
    out=[]
    for a,b in sorted(intervals):
        if out and a<=out[-1][1]: out[-1][1]=max(out[-1][1],b)
        else: out.append([a,b])
    return out

def apply_transactions(start,operations):
    balance=start; declined=[]
    for id,kind,amount in operations:
        if kind=="credit": balance+=amount
        elif amount<=balance: balance-=amount
        else: declined.append(id)
    return {"balance":balance,"declined":declined}

def rle_encode(text):
    out=[]
    for c in text:
        if out and out[-1][0]==c: out[-1][1]+=1
        else: out.append([c,1])
    return out

def deep_get(value,path,default):
    for p in path:
        if isinstance(value,dict) and isinstance(p,str) and p in value: value=value[p]
        elif isinstance(value,list) and isinstance(p,int) and 0<=p<len(value): value=value[p]
        else: return default
    return value
